begin;insert into public.security_permissions(codigo,modulo,nome,criticidade)values('payroll.import.read','folha','Consultar importações','sensivel'),('payroll.import.manage','folha','Importar variáveis em lote','critica')on conflict(codigo)do update set nome=excluded.nome;insert into public.security_role_permissions(role_id,permission_id)select r.id,p.id from public.security_roles r join public.security_permissions p on p.codigo in('payroll.import.read','payroll.import.manage')where r.codigo='tenant_admin'on conflict do nothing;
create table public.payroll_import_batches(id uuid primary key default gen_random_uuid(),tenant_id uuid not null references public.tenants(id),file_name text not null,file_type text not null,reference_month date not null,status text not null default'validando',total_rows int not null,valid_rows int not null default 0,error_rows int not null default 0,file_sha256 text not null,created_by uuid references public.profiles(id),created_at timestamptz default now(),committed_at timestamptz,check(file_type in('txt','csv','xlsx')),check(status in('validando','pre_validado','com_erros','importado','cancelado')),check(reference_month=date_trunc('month',reference_month)::date),check(file_sha256~'^[0-9a-f]{64}$'));
create table public.payroll_import_rows(id bigint generated always as identity primary key,tenant_id uuid not null references public.tenants(id),batch_id uuid not null references public.payroll_import_batches(id),row_number int not null,raw_data jsonb not null,employment_link_id uuid references public.employment_links(id),rubric_id uuid references public.payroll_rubrics(id),amount numeric(16,2),installments int,error_codes jsonb not null default'[]',status text not null,check(status in('valida','invalida','importada')),unique(batch_id,row_number));
create table public.payroll_monthly_variables(id uuid primary key default gen_random_uuid(),tenant_id uuid not null references public.tenants(id),employment_link_id uuid not null references public.employment_links(id),rubric_id uuid not null references public.payroll_rubrics(id),reference_month date not null,amount numeric(16,2) not null,installment_number int not null default 1,installments_total int not null default 1,source_batch_id uuid references public.payroll_import_batches(id),created_at timestamptz default now(),check(amount>=0),check(installment_number between 1 and installments_total),unique(employment_link_id,rubric_id,reference_month,source_batch_id));
alter table public.payroll_import_batches enable row level security;alter table public.payroll_import_rows enable row level security;alter table public.payroll_monthly_variables enable row level security;do $$begin if to_regnamespace('auth')is not null then create policy import_batch on public.payroll_import_batches for all to authenticated using(private.has_tenant_permission(tenant_id,'payroll.import.read'))with check(private.has_tenant_permission(tenant_id,'payroll.import.manage'));create policy import_rows on public.payroll_import_rows for all to authenticated using(private.has_tenant_permission(tenant_id,'payroll.import.read'))with check(private.has_tenant_permission(tenant_id,'payroll.import.manage'));create policy monthly_variables on public.payroll_monthly_variables for all to authenticated using(private.has_tenant_permission(tenant_id,'payroll.import.read'))with check(private.has_tenant_permission(tenant_id,'payroll.import.manage'));end if;end$$;revoke all on public.payroll_import_batches,public.payroll_import_rows,public.payroll_monthly_variables from anon;do $$begin if exists(select 1 from pg_roles where rolname='authenticated')then grant select,insert,update on public.payroll_import_batches,public.payroll_import_rows,public.payroll_monthly_variables to authenticated;grant usage,select on sequence public.payroll_import_rows_id_seq to authenticated;end if;end$$;commit;
